CREATE TABLE IF NOT EXISTS hospedes (id_hospede INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nome VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,telefone VARCHAR(20));
CREATE TABLE IF NOT EXISTS reservas (id_reserva INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_hospede INTEGER NOT NULL REFERENCES hospedes(id_hospede),data_checkin DATE NOT NULL,data_checkout DATE NOT NULL,valor_diaria NUMERIC(10,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ATIVA',CONSTRAINT ck_reservas_datas CHECK(data_checkout>data_checkin),CONSTRAINT ck_reservas_diaria CHECK(valor_diaria>0),CONSTRAINT ck_reservas_status CHECK(status IN ('ATIVA','CANCELADA','FINALIZADA')));
CREATE INDEX IF NOT EXISTS ix_reservas_hospede ON reservas(id_hospede);
CREATE INDEX IF NOT EXISTS ix_reservas_checkin ON reservas(data_checkin);
